using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PurchaseInvoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PurchaseInvoices.Commands.CancelPurchaseInvoice;public sealed class CancelPurchaseInvoiceCommandHandler(IPurchaseInvoiceRepository repository,IApplicationDbContext db):IRequestHandler<CancelPurchaseInvoiceCommand,Result<PurchaseInvoiceDto>>{public async Task<Result<PurchaseInvoiceDto>>Handle(CancelPurchaseInvoiceCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.NotFound);if(e.Status!="Draft")return Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.NotDraft);e.Cancel();await db.SaveChangesAsync(cancellationToken);return Result.Success(PurchaseInvoiceDto.FromEntity(e));}}
